import{_ as a,C as t,o,c as r,E as i,a2 as c}from"./chunks/framework.DyLyN3RJ.js";const b=JSON.parse('{"title":"A Confirmed Submission Still Needs Process Evidence","description":"","frontmatter":{"title":"A Confirmed Submission Still Needs Process Evidence","article_type":"engineering-insight","edition":"research-center","research_question":"草稿确认能确立什么，还需要哪些过程证据？","summary":"Draft confirmation constrains submitted content and authority. A reported counterexample and internal statistical reanalysis show why process fulfillment and mechanism benefits need separate evidence boundaries.","research_question_en":"What does draft confirmation establish, and what process evidence remains necessary?","sources":["https://arxiv.org/html/2610.25954v1"],"date":"2026-11-11","column":"digital-employee","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261111-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-11-sig-20261111-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-11-11-sig-20261111-005.md","filePath":"en/digital-employee/2026-11-11-sig-20261111-005.md","lastUpdated":1794406624000}'),d={name:"en/digital-employee/2026-11-11-sig-20261111-005.md"};function l(h,e,p,m,u,f){const n=t("ArticleCover"),s=t("ArticleTableScroll");return o(),r("div",null,[i(n,{image:"/assets/covers/daily-2026-11-11-sig-20261111-005-cover.png",kicker:"Research",title:"A Confirmed Submission Still Needs Process Evidence",summary:"Draft confirmation constrains submitted content and authority. A reported counterexample and internal statistical reanalysis show why process fulfillment and mechanism benefits need separate evidence boundaries.",version:"2026-11-11",languageHref:"/zh/digital-employee/2026-11-11-sig-20261111-005",languageLabel:"中文"}),i(s,{language:"en"}),e[0]||(e[0]=c('<h1 id="a-confirmed-submission-still-needs-process-evidence" tabindex="-1">A Confirmed Submission Still Needs Process Evidence <a class="header-anchor" href="#a-confirmed-submission-still-needs-process-evidence" aria-label="Permalink to &quot;A Confirmed Submission Still Needs Process Evidence&quot;">​</a></h1><p>Draft confirmation constrains submitted content and authority. A reported counterexample and internal statistical reanalysis show why process fulfillment and mechanism benefits need separate evidence boundaries.</p><h2 id="the-right-version-can-leave-the-task-incomplete" tabindex="-1">The right version can leave the task incomplete <a class="header-anchor" href="#the-right-version-can-leave-the-task-incomplete" aria-label="Permalink to &quot;The right version can leave the task incomplete&quot;">​</a></h2><p>In the insurance trace reported by CXBench, the second draft reaches the correct submitted result yet fails process acceptance. A reporter-authority check is missing; the semantic judge also flags insufficient existing-claim context and notice carry-forward after revision. This is an author-reported trace, not an insurance transaction rerun here or a legal-compliance finding. <a href="https://arxiv.org/html/2610.25954v1" target="_blank" rel="noreferrer">Section G.4 of the paper</a> supplies the counterexample.</p><p>The distinction is between which version was confirmed and which obligations had to be fulfilled earlier. In the paper&#39;s mediated mode, submission tools are removed from the agent&#39;s available actions. The execution environment checks a draft hash and task-designated fields before submitting. A hash binds confirmation to content; it does not itself record every prior disclosure, identity check or notice association after revision. Process acceptance additionally combines deterministic rules and a semantic judge. Overall success requires both outcome and process acceptance.</p><p>Confirmation therefore has a useful, bounded job: constrain content and authority at the final action. A successful receipt cannot retrospectively establish the entire process. These are obligations encoded by the benchmark; its observable checkpoints are not automatically statutory deadlines or certification criteria.</p><h2 id="read-the-denominator-and-the-rejection-mechanism" tabindex="-1">Read the denominator and the rejection mechanism <a class="header-anchor" href="#read-the-denominator-and-the-rejection-mechanism" aria-label="Permalink to &quot;Read the denominator and the rejection mechanism&quot;">​</a></h2><p>Of the authors&#39; 840 retained evaluation records, 582 pass the business outcome, 116 pass both outcome and process, and 466 pass the outcome while failing the process. The last count is 55.48% of all retained records but 80.07% of outcome-passing records. Those denominators answer different questions. With network-only retries in the retention protocol, neither estimates first-attempt deployment failure probability.</p><p>The same-run internal statistical reanalysis decomposes the 466 reported records into 38 rejected only by deterministic checks, 329 only by semantic checks, and 99 by both. Removing all deterministic checks therefore adds only 38 passes: 428 remain rejected semantically. Removing all semantic checks adds 329 passes. This decomposes reported counts; it does not grade fresh traces.</p><p>The overlap explains why a local mechanism cannot replace all process evidence. It does not establish that semantic grading is more reliable. The reported human comparison uses one expert and 120 calibration traces from one agent model, with 88.33% accuracy and 69.70% pass precision. Sections E.3 and H.4 also conflict over the judge-model identity. A larger number of rejections is not independent validation of those judgments.</p><h2 id="a-policy-change-narrows-the-benefit-claim" tabindex="-1">A policy change narrows the benefit claim <a class="header-anchor" href="#a-policy-change-narrows-the-benefit-claim" aria-label="Permalink to &quot;A policy change narrows the benefit claim&quot;">​</a></h2><p>The original comparison reports both-pass rates of 20.83% for mediated submission and 0.83% for direct submission, while scoring includes direct-submission-specific prohibitions. Excluding mechanism-specific checks changes the rates to 20.83% and 18.33%. These gaps use different scoring policies. The original 20-point gap cannot directly establish a causal execution benefit.</p><p>For the excluded-check condition, the authors report 120 pairs: 12 pass both ways, 13 only mediated, 10 only direct, and 85 neither. Internal reanalysis of those contingencies gives direct minus mediated of −2.5 percentage points and an exact two-sided paired-test p-value of 0.677639. A seeded 100,000-resample paired bootstrap gives a 95% interval of [−10, 5] percentage points. Reconstructed categories cannot recover task identities or trace content; the bootstrap resamples reported pairs rather than new agent executions.</p><p>This condition establishes neither an additional mediated benefit nor equivalence. The interval permits differences in either direction. The paper also describes reusing recorded traces while final-state counts change. Without verifiable companion execution material, that transformation remains independently untraceable. Matching the calculation establishes what statistical statement follows from the counts, not whether the underlying labels or execution were correct.</p><h2 id="preserve-the-distinctions-in-acceptance-records" tabindex="-1">Preserve the distinctions in acceptance records <a class="header-anchor" href="#preserve-the-distinctions-in-acceptance-records" aria-label="Permalink to &quot;Preserve the distinctions in acceptance records&quot;">​</a></h2><p>Our engineering interpretation is that acceptance records for genuinely process-constrained digital employees should distinguish the business outcome, who confirmed which content version, and evidence for required process obligations. This is a record-design judgment, not a generally validated architecture. Comparisons should hold scoring policy fixed and expose excluded rules and unmet obligations separately, so that successful tool submission does not erase process information.</p><p>The same checks are not appropriate for every task. A contract requiring only a final artifact does not justify importing an entire industry&#39;s process. A contract that explicitly includes identity, notice or revision obligations calls for evidence of those obligations. The question to test is whether such records help locate omissions and reduce mistaken acceptance without turning an unreliable judge into a new single point of judgment.</p><h2 id="evidence-and-sources-what-is-still-missing" tabindex="-1">Evidence and sources: what is still missing <a class="header-anchor" href="#evidence-and-sources-what-is-still-missing" aria-label="Permalink to &quot;Evidence and sources: what is still missing&quot;">​</a></h2><p><a href="https://arxiv.org/html/2610.25954v1" target="_blank" rel="noreferrer">CXBench version 1</a> is the authors&#39; primary material for mechanism definitions, traces and evaluation counts. Public definitions are source facts; results remain author reports. Internal reanalysis examines consequences of the reported counts, while engineering recommendations are our interpretation. None constitutes an outside independent replication. No concrete companion-download address was confirmed, and no new business execution was performed.</p><p>The missing evidence is versioned execution code and original traces, an explanation of direct-submission state transformation, and held-out judge-error and rule-mapping agreement measurements. Publication establishes provenance and version, not validity. Citation is not endorsement; peer review is not proof; self-reported results are not independent evidence; implementation success does not establish general validity. Until these gaps close, the supported judgment is to distinguish the two evidence responsibilities, not to declare a submission mechanism comprehensively superior.</p><p>Internal research material: <a href="/joinwell52/assets/evidence/2026-11-11-sig-20261111-005/cx-paired.json">paired counts, bootstrap settings and rejection decomposition</a>. These files preserve completed internal calculations, not an independent replication.</p>',21))])}const v=a(d,[["render",l]]);export{b as __pageData,v as default};
